package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.dto.Requests; import com.agencytrip.agencytripapi.application.service.ReservationService; import com.agencytrip.agencytripapi.domain.model.Reservation; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/Reservas") public class ReservationController {private final ReservationService s;public ReservationController(ReservationService s){this.s=s;}@GetMapping public Object list(@AuthenticationPrincipal Jwt jwt){return (role(jwt).equals("CLIENTE")?s.byUser(id(jwt)):s.all()).stream().map(ApiResponses::reservation).toList();}@PostMapping public Object create(@AuthenticationPrincipal Jwt jwt,@Valid@RequestBody Requests.Reservation r){Reservation x=s.create(id(jwt),r);return Map.of("mensaje","Reserva creada correctamente.","reserva",ApiResponses.reservation(x));}@PutMapping("/{id}/estado")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object status(@PathVariable int id,@Valid@RequestBody Requests.ReservationStatus r){s.changeStatus(id,r);return Map.of("mensaje","Estado de la reserva actualizado correctamente.");}static int id(Jwt j){return ((Number)j.getClaim("userId")).intValue();}static String role(Jwt j){return j.getClaimAsStringList("roles").getFirst();}}
